select.where:
h.del_flag = '0' and h.honor_id = #{honorId}

    and exists (
        select 1 from honor_relation hr
        left join project p   on hr.ref_type='PROJECT'    and hr.ref_id = p.project_id and p.del_flag='0'
        left join sys_user su on hr.ref_type='RESEARCHER' and hr.ref_id = su.user_id
        left join sys_dept d  on d.dept_id = coalesce(p.dept_id, su.dept_id)
        left join sys_user u  on u.user_id = p.leader_id
        where hr.honor_id = h.honor_id and hr.del_flag='0'
        ${params.dataScope}
    )

mapper.select:

where h.del_flag = '0' and h.honor_id = #{honorId}
  and (
    exists (select 1 from honor_relation hr where hr.honor_id = h.honor_id and hr.del_flag='0'
            and hr.ref_type='RESEARCHER' and hr.ref_id = #{selfUserId})
    or exists (select 1 from honor_relation hr join project p on hr.ref_id = p.project_id and p.del_flag='0'
            where hr.honor_id = h.honor_id and hr.del_flag='0' and hr.ref_type='PROJECT'
            and (p.leader_id = #{selfUserId}
                 or exists (select 1 from project_member m where m.project_id = p.project_id
                            and m.user_id = #{selfUserId} and m.del_flag='0')))
    or h.create_by = #{selfUsername}
  )
